    'Idli' => ['name_ta' => 'இட்லி',
        'notes' => 'Scaling: one grinder batch of 6 kg rice is about 100 people; for 250–500 grind in separate batches and ferment in several containers (never more than half full). Batter that smells sour-bitter or has pink/grey patches must be discarded.',
        'notes_ta' => 'அளவு: 6 கிலோ அரிசி ஒரு கிரைண்டர் = சுமார் 100 பேர்; 250–500 பேருக்கு தனித்தனியாக அரைத்து, பல பாத்திரங்களில் (பாதி அளவுக்கு மேல் நிரப்பாமல்) புளிக்க விடவும். கசப்பு வாசனை அல்லது பிங்க்/சாம்பல் நிற படலம் இருந்தால் மாவை தூக்கி எறியவும்.',
        'steps_ta' => [
            $t('ஊற வைத்தல்', 'அரிசியை மூன்று முறை கழுவி 5–6 மணி நேரம் ஊற வைக்கவும். உளுந்தையும் வெந்தயத்தையும் கழுவி தனி பாத்திரத்தில் 4 மணி நேரம் ஊற வைக்கவும்; இரண்டையும் மூடி குளிர்ந்த இடத்தில் வைக்கவும்.'),
            $t('அரைத்தல்', 'உளுந்தை கிரைண்டரில் குளிர்ந்த தண்ணீரை கொஞ்சம் கொஞ்சமாக சேர்த்து 25–30 நிமிடம் அரைக்கவும் — மாவு பஞ்சு போல் லேசாகி இரண்டு மடங்கு ஆக வேண்டும். அரிசியை ரவை போல் கொஞ்சம் கரகரப்பாக அரைக்கவும்.'),
            $t('கலந்து புளிக்க விடுதல்', 'இரண்டு மாவையும் உப்புடன் கையால் நன்றாக கலக்கவும். சுத்தமான பாத்திரத்தில் பாதி அளவு மட்டும் நிரப்பி, மூடி 8–10 மணி நேரம் புளிக்க விடவும் — மாவு பொங்கி லேசான புளிப்பு வாசனை வர வேண்டும்.'),
            $t('வேக வைத்தல்', 'இட்லி தட்டுகளில் எண்ணெய் தடவி, முக்கால் அளவு மாவு ஊற்றி, அதிக தீயில் 10–12 நிமிடம் ஆவியில் வேக வைக்கவும். குச்சியை குத்தினால் ஒட்டாமல் வர வேண்டும். 2 நிமிடம் கழித்து எடுக்கவும்.'),
            $t('சூடாக வைத்தல்', 'இட்லியை மூடிய ஹாட் பாக்ஸில் 65 °C க்கு மேல் சூடாக வைத்து 2 மணி நேரத்துக்குள் பரிமாறவும். தட்டுகளை 4 அடுக்குக்கு மேல் அடுக்க வேண்டாம், கீழே உள்ளவை ஈரமாகிவிடும்.'),
        ]],
    'Ven Pongal' => ['name_ta' => 'வெண் பொங்கல்',
        'notes' => 'Pongal thickens fast while holding — keep hot water ready to loosen it. For 250+ cook in two vessels; a single huge vessel burns at the bottom.',
        'notes_ta' => 'பொங்கல் வைத்திருக்கும் போது கெட்டியாகும் — தளர்த்த சுடு தண்ணீர் தயாராக வைக்கவும். 250 பேருக்கு மேல் இரண்டு பாத்திரங்களில் சமைக்கவும்; ஒரே பெரிய பாத்திரத்தில் அடிபிடிக்கும்.',
        'steps_ta' => [
            $t('பருப்பு வறுத்தல்', 'பாசிப் பருப்பை கனமான வாணலியில் மிதமான தீயில் 6–8 நிமிடம் வாசனை வரும் வரை, லேசான பொன்னிறமாக வறுக்கவும்; பழுப்பு நிறமாகக் கூடாது.'),
            $t('அரிசி பருப்பு வேக வைத்தல்', '22 லிட்டர் தண்ணீர் கொதிக்க வைத்து அரிசியும் வறுத்த பருப்பும் சேர்க்கவும். மூடியை பாதி திறந்து மிதமான தீயில் 30–35 நிமிடம், 5 நிமிடத்துக்கு ஒரு முறை அடியில் இருந்து கிளறி, நன்றாக குழைய வேக விடவும்.'),
            $t('உப்பு சேர்த்தல்', 'கரண்டியால் லேசாக மசித்து உப்பு சேர்க்கவும். சுடு தண்ணீர் சேர்த்து பதம் சரிசெய்யவும் — கரண்டியில் இருந்து மெதுவாக விழும் பதம் வேண்டும், ஆறும் போது கெட்டியாகும்.'),
            $t('தாளித்தல்', 'நெய்யை மிதமான தீயில் சூடாக்கி முந்திரியை பொன்னிறமாக வறுக்கவும்; மிளகு, சீரகம், இஞ்சி, கறிவேப்பிலை சேர்த்து 30 வினாடி வாசனை வந்ததும் பொங்கலில் ஊற்றவும். நன்றாக கிளறி 65 °C க்கு மேல் மூடி வைக்கவும்.'),
        ]],
    'Rava Upma' => ['name_ta' => 'ரவா உப்புமா',
        'notes' => 'Roast rava a day ahead for big orders. For 250+ cook in batches of 100 — rava added to too much water at once forms lumps.',
        'notes_ta' => 'பெரிய ஆர்டருக்கு ரவையை முந்தைய நாளே வறுத்து வைக்கலாம். 250 பேருக்கு மேல் 100 பேர் அளவில் தனித்தனியாக செய்யவும் — ஒரே நேரத்தில் அதிக தண்ணீரில் ரவை போட்டால் கட்டியாகும்.',
        'steps_ta' => [
            $t('ரவை வறுத்தல்', 'ரவையை குறைந்த தீயில் தொடர்ந்து கிளறி 8–10 நிமிடம் வாசனை வரும் வரை, நிறம் மாறாமல் வறுக்கவும். தட்டில் பரப்பி ஆற விடவும்.'),
            $t('தாளித்தல்', $tempTa.' இஞ்சி, பச்சை மிளகாய், வெங்காயம் சேர்த்து வெங்காயம் கண்ணாடி போல் ஆகும் வரை சுமார் 5 நிமிடம் வதக்கவும்.'),
            $t('தண்ணீர் கொதிக்க வைத்தல்', '15 லிட்டர் தண்ணீரும் உப்பும் சேர்த்து அதிக தீயில் நன்றாக கொதிக்க விடவும்; தண்ணீர் சற்று உப்பாக இருக்க வேண்டும்.'),
            $t('ரவை சேர்த்தல்', 'தீயை மிதமாக்கி, ஒருவர் தொடர்ந்து கிளற, இன்னொருவர் ரவையை மெல்லிய தாரையாக கொட்டவும் — கட்டி வரக்கூடாது. மூடி குறைந்த தீயில் 5 நிமிடம் வேக விடவும். உதிர்த்து 65 °C க்கு மேல் வைக்கவும்.'),
        ]],
    'Medu Vadai' => ['name_ta' => 'மெது வடை',
        'notes' => 'Fry in batches; keep oil at 165–175 °C. Never top up old dark oil with fresh oil — change it. Keep a fire blanket near the fryer.',
        'notes_ta' => 'தொகுதி தொகுதியாக பொரிக்கவும்; எண்ணெய் 165–175 °C இல் இருக்க வேண்டும். கருத்த பழைய எண்ணெயில் புதிய எண்ணெய் சேர்க்க வேண்டாம் — மாற்றவும். பொரிப்பான் அருகே தீ அணைப்பு போர்வை வைக்கவும்.',
        'steps_ta' => [
            $t('அரைத்தல்', 'ஊறிய உளுந்தை நன்றாக வடித்து, மிகக் குறைந்த குளிர்ந்த தண்ணீர் தெளித்து 20 நிமிடம் அரைக்கவும் — மாவு பஞ்சு போல் கெட்டியாக இருக்க வேண்டும்; ஒரு துளி மாவு தண்ணீரில் மிதக்க வேண்டும்.'),
            $t('கலத்தல்', 'பொரிப்பதற்கு சற்று முன் வெங்காயம், மிளகாய், இஞ்சி, மிளகு, கறிவேப்பிலை, உப்பு சேர்க்கவும் — உப்பை முன்பே போட்டால் மாவு நீர்த்துவிடும்.'),
            $t('பொரித்தல்', 'எண்ணெயை சுமார் 170 °C க்கு சூடாக்கவும் (மாவு போட்டதும் மேலே வர வேண்டும்). ஈரக் கையால் வடை தட்டி ஓட்டை போட்டு எண்ணெயில் விடவும். மிதமான தீயில் 4–5 நிமிடம் திருப்பி பொன்னிறமாக மொறுமொறுப்பாக பொரிக்கவும்.'),
            $t('வடித்து வைத்தல்', 'ஓட்டை தட்டுகளில் அடுக்காமல் வடிக்கவும்; திறந்த வார்மரில் வைத்து 1 மணி நேரத்துக்குள் பரிமாறவும். கருத்த அல்லது நுரை வரும் எண்ணெயை வடிகட்டி எறியவும்.'),
        ]],
    'Chapati' => ['name_ta' => 'சப்பாத்தி',
        'notes' => 'For 250+ use 2–3 tawas with one roller per tawa. Dough can be kneaded 2 hours ahead and kept covered in the chiller.',
        'notes_ta' => '250 பேருக்கு மேல் 2–3 தோசைக்கல், ஒவ்வொன்றுக்கும் ஒரு உருட்டுபவர். மாவை 2 மணி நேரம் முன்பே பிசைந்து மூடி குளிர்சாதனத்தில் வைக்கலாம்.',
        'steps_ta' => [
            $t('பிசைதல்', 'கோதுமை மாவும் உப்பும் கலந்து, வெதுவெதுப்பான தண்ணீர் கொஞ்சம் கொஞ்சமாக சேர்த்து 10 நிமிடம் மென்மையாக, கையில் ஒட்டாமல் பிசையவும். எண்ணெய் தடவி மூடி 30 நிமிடம் வைக்கவும்.'),
            $t('உருண்டை உருட்டுதல்', '35–40 கிராம் உருண்டைகளாக பிரித்து, லேசாக மாவு தூவி 6 அங்குல வட்டமாக சமமாக தேய்க்கவும்; தேய்த்தவற்றை காய்ந்துவிடாமல் மூடி வைக்கவும்.'),
            $t('சுடுதல்', 'சூடான தோசைக்கல்லில் (மிதமான-அதிக தீ) 30 வினாடி குமிழ் வரும் வரை சுட்டு, திருப்பி 30 வினாடி, ஓரங்களை அழுத்தினால் உப்பும். லேசாக எண்ணெய் தடவவும்.'),
            $t('சூடாக வைத்தல்', 'துணி விரித்த கேசரோல் அல்லது ஹாட் பாக்ஸில் அடுக்கி 1 மணி நேரத்துக்குள் பரிமாறவும்; சூடான சப்பாத்தியை பிளாஸ்டிக்கில் மூடினால் ஈரமாகும்.'),
        ]],
    'Coconut Chutney' => ['name_ta' => 'தேங்காய் சட்னி',
        'notes' => 'High-risk item: grind close to service, keep chilled, never mix old chutney with new.',
        'notes_ta' => 'சீக்கிரம் கெட்டுப்போகும்: பரிமாறும் நேரத்துக்கு அருகில் அரைக்கவும், குளிர்ச்சியாக வைக்கவும், பழைய சட்னியை புதியதுடன் கலக்க வேண்டாம்.',
        'steps_ta' => [
            $t('அரைத்தல்', 'தேங்காய், பொட்டுக்கடலை, பச்சை மிளகாய், இஞ்சி, உப்பு சேர்த்து குளிர்ந்த தண்ணீருடன் பகுதி பகுதியாக நைசாக, கெட்டியாக அரைக்கவும்; குளிர்ந்த தண்ணீர் சட்னி பிரியாமல் இருக்க உதவும்.'),
            $t('தாளித்தல்', $tempTa.' சட்னியில் ஊற்றி கலக்கவும்.'),
            $t('பாதுகாப்பாக வைத்தல்', 'தேங்காய் சட்னி சீக்கிரம் கெடும்: பரிமாறும் வரை 5 °C க்கு கீழ் வைக்கவும், அரைத்து 2 மணி நேரத்துக்குள் பரிமாறவும், மீதியை சேவை முடிந்ததும் எறியவும்.'),
        ]],
    'Tiffin Sambar' => ['name_ta' => 'டிஃபன் சாம்பார்',
        'notes' => 'For 250+ cook dal in two cookers and combine in one large vessel; add water gradually — tiffin sambar should stay pourable.',
        'notes_ta' => '250 பேருக்கு மேல் பருப்பை இரண்டு குக்கரில் வேக வைத்து ஒரு பெரிய பாத்திரத்தில் சேர்க்கவும்; தண்ணீரை படிப்படியாக சேர்க்கவும் — டிஃபன் சாம்பார் ஊற்றும் பதத்தில் இருக்க வேண்டும்.',
        'steps_ta' => [
            $t('பருப்பு வேக வைத்தல்', 'துவரம் பருப்பை மஞ்சள் தூள், 9 லிட்டர் தண்ணீருடன் குக்கரில் 4–5 விசில் வரை முழுமையாக குழைய வேக வைத்து நைசாக மசிக்கவும்.'),
            $t('வெங்காயம் தக்காளி வதக்குதல்', 'எண்ணெயில் கடுகு வெடித்ததும் பெருங்காயம், கறிவேப்பிலை சேர்த்து, சின்ன வெங்காயத்தை 6–8 நிமிடம் மென்மையாக லேசான பொன்னிறமாக வதக்கி, தக்காளி சேர்த்து குழைய வதக்கவும்.'),
            $t('கொதிக்க விடுதல்', 'புளிக்கரைசல், சாம்பார் பொடி, உப்பு, மீதி தண்ணீர் சேர்த்து புளி வாசனை போகும் வரை 10 நிமிடம் கொதிக்க விடவும். பருப்பு சேர்த்து 10 நிமிடம் கொதிக்க விடவும் — ஊற்றும் பதத்தில் சற்று நீர்த்து இருக்க வேண்டும்.'),
            $t('முடித்தல்', 'கொத்தமல்லி சேர்த்து 65 °C க்கு மேல் மூடி வைக்கவும்; ஒவ்வொரு முறை பரிமாறும் முன் அடியில் இருந்து கிளறவும்.'),
        ]],
    'Steamed Rice' => ['name_ta' => 'சாதம்',
        'notes' => 'For 250+ boil in several vessels of up to 15 kg rice each. Cooked rice left warm (20–50 °C) can grow Bacillus cereus — keep it hot or cool it fast.',
        'notes_ta' => '250 பேருக்கு மேல் ஒரு பாத்திரத்தில் 15 கிலோவுக்கு மேல் இல்லாமல் பல பாத்திரங்களில் வடிக்கவும். வெதுவெதுப்பாக (20–50 °C) வைத்த சாதத்தில் கிருமி வளரும் — சூடாக வைக்கவும் அல்லது சீக்கிரம் ஆற வைக்கவும்.',
        'steps_ta' => [
            $t('கழுவுதல்', 'அரிசியை தண்ணீர் தெளிவாகும் வரை 2–3 முறை கழுவி, சமமாக வேக 20 நிமிடம் ஊற வைக்கவும்.'),
            $t('கொதிக்க வைத்தல்', 'பெரிய பாத்திரத்தில் தண்ணீரை நன்றாக கொதிக்க வைத்து அரிசி சேர்த்து ஒரு முறை கிளறி, மூடாமல் மிதமான-அதிக தீயில் 15–18 நிமிடம் வேக விடவும். ஒரு பருக்கையை அழுத்திப் பார்க்கவும்: நடுவில் வெள்ளை இல்லாமல் மென்மையாக இருக்க வேண்டும்.'),
            $t('வடித்து வைத்தல்', 'பெரிய வடிகட்டியில் கஞ்சியை வடித்து, மீண்டும் பாத்திரத்தில் போட்டு மூடி அடுப்பில் இருந்து இறக்கி 10 நிமிடம் வைக்கவும் — பருக்கைகள் உதிரியாகும். 65 °C க்கு மேல் வைக்கவும்.'),
        ]],
    'Lemon Rice' => ['name_ta' => 'எலுமிச்சை சாதம்',
        'notes' => 'Add lemon juice off the heat — boiling lemon turns it bitter. For 250+ mix in batches of 10 kg rice.',
        'notes_ta' => 'எலுமிச்சை சாற்றை அடுப்பை அணைத்த பிறகு சேர்க்கவும் — கொதித்தால் கசக்கும். 250 பேருக்கு மேல் 10 கிலோ அரிசி அளவில் தனித்தனியாக கலக்கவும்.',
        'steps_ta' => [
            $t('சாதம் வடித்தல்', 'சாதத்தை உதிரியாக (சற்று கெட்டியாக) வடித்து தட்டுகளில் பரப்பி 15 நிமிடம் ஆற விடவும் — கலக்கும் போது பருக்கை உடையாது.'),
            $t('தாளித்தல்', 'மிதமான தீயில் எண்ணெயில் வேர்க்கடலையை மொறுமொறுப்பாக வறுத்து, கடுகு, கடலைப் பருப்பு, உளுத்தம் பருப்பு பொன்னிறமாக வறுக்கவும்; மிளகாய், இஞ்சி, கறிவேப்பிலை, பெருங்காயம், மஞ்சள் தூள் 30 வினாடி — மஞ்சள் கருகக் கூடாது.'),
            $t('கலத்தல்', 'அடுப்பை அணைத்து எலுமிச்சை சாறும் உப்பும் தாளிப்பில் சேர்த்து, சாதத்தில் ஊற்றி தட்டையான கரண்டியால் மெதுவாக மஞ்சள் நிறம் சமமாக வரும் வரை கலக்கவும். ருசி பார்த்து எலுமிச்சை, உப்பு சரிசெய்யவும்.'),
            $t('வைத்தல்', 'அறை வெப்பத்தில் 3 மணி நேரம் வரை அல்லது 65 °C க்கு மேல் மூடி வைக்கவும்; எலுமிச்சை சாதம் வெதுவெதுப்பாக பரிமாறப்படும்.'),
        ]],
    'Tamarind Rice' => ['name_ta' => 'புளியோதரை',
        'notes' => 'The puli paste keeps 2 weeks refrigerated — make it a day ahead for big events and mix rice on the day.',
        'notes_ta' => 'புளிக்காய்ச்சல் குளிர்சாதனத்தில் 2 வாரம் இருக்கும் — பெரிய நிகழ்ச்சிக்கு முந்தைய நாளே செய்து, அன்று சாதத்தில் கலக்கவும்.',
        'steps_ta' => [
            $t('புளி கரைசல்', 'ஊறிய புளியை பிழிந்து வடிகட்டி சுமார் 6 லிட்டர் கெட்டியான கரைசல் எடுக்கவும்.'),
            $t('புளிக்காய்ச்சல்', 'நல்லெண்ணெயில் வேர்க்கடலை, பின் கடுகு, பருப்புகள், காய்ந்த மிளகாய் பொன்னிறமாக வறுக்கவும்; கறிவேப்பிலை, பெருங்காயம், மஞ்சள் தூள், புளிக்கரைசல், உப்பு, வெல்லம் சேர்த்து மிதமான தீயில் அடிக்கடி கிளறி 30–35 நிமிடம் கெட்டியாகி ஓரத்தில் எண்ணெய் பிரியும் வரை கொதிக்க விடவும்.'),
            $t('கலத்தல்', 'வெந்தயப் பொடி சேர்த்து, சற்று ஆறிய புளிக்காய்ச்சலை ஆறிய சாதத்தில் பகுதி பகுதியாக தட்டையான கரண்டியால் கலக்கவும். சுவை ஊற 30 நிமிடம் வைக்கவும்.'),
        ]],
    'Curd Rice' => ['name_ta' => 'தயிர் சாதம்',
        'notes' => 'Keep chilled until service — curd rice in the sun or a warm hall sours and can make guests ill within hours.',
        'notes_ta' => 'பரிமாறும் வரை குளிர்ச்சியாக வைக்கவும் — வெயிலில் அல்லது சூடான அரங்கில் தயிர் சாதம் சில மணி நேரத்தில் புளித்து உடல்நலக் கேடு ஏற்படுத்தும்.',
        'steps_ta' => [
            $t('சாதம் வேக வைத்து ஆற வைத்தல்', 'கூடுதல் தண்ணீருடன் சாதத்தை நன்றாக குழைய வேக வைத்து லேசாக மசித்து அறை வெப்பத்துக்கு (30 °C க்கு கீழ்) ஆற விடவும் — சூடான சாதத்தில் தயிர் சேர்த்தால் சீக்கிரம் புளிக்கும்.'),
            $t('கலத்தல்', 'தயிர், பால், உப்பு சேர்த்து கிரீம் போல் கலக்கவும்; வைத்திருக்கும் போது கெட்டியாகும், அதனால் சற்று தளர்வாக வைக்கவும்.'),
            $t('தாளித்து குளிர்வித்தல்', $tempTa.' இஞ்சி, மிளகாய் சேர்த்து சாதத்தில் ஊற்றி கொத்தமல்லி சேர்த்து கலக்கவும். 8 °C க்கு கீழ் வைத்து 4 மணி நேரத்துக்குள் பரிமாறவும்.'),
        ]],
    'Vegetable Biryani' => ['name_ta' => 'வெஜிடபிள் பிரியாணி',
        'notes' => 'Covers vegetable dum biryani. Keep water at 1.5× rice by volume. For 250+ cook in separate 10 kg-rice vessels; dum time stays 20 minutes per vessel.',
        'notes_ta' => 'வெஜிடபிள் டம் பிரியாணிக்கும் இதுவே. தண்ணீர் அரிசியின் 1.5 மடங்கு. 250 பேருக்கு மேல் 10 கிலோ அரிசி அளவில் தனித்தனி பாத்திரங்களில் செய்யவும்; ஒவ்வொரு பாத்திரத்துக்கும் டம் நேரம் 20 நிமிடம்தான்.',
        'steps_ta' => [
            $t('மசாலா', 'எண்ணெய், நெய் சூடாக்கி முழு மசாலாவை 30 வினாடி வறுத்து, வெங்காயத்தை மிதமான தீயில் 15 நிமிடம் பொன்னிறமாக வதக்கவும். இஞ்சி பூண்டு விழுது பச்சை வாசனை போகும் வரை, பின் தக்காளி, மிளகாய் தூள், பிரியாணி மசாலா சேர்த்து எண்ணெய் பிரியும் வரை வதக்கவும்.'),
            $t('காய்கறிகள்', 'காய்கறிகள், தயிர், பாதி புதினா கொத்தமல்லி, உப்பு சேர்த்து 8–10 நிமிடம் காய்கறி பாதி வேகும் வரை சமைக்கவும்.'),
            $t('அரிசி', '15 லிட்டர் தண்ணீர் சேர்த்து கொதிக்க வைத்து ருசி பார்க்கவும் — சற்று அதிக உப்பாக இருக்க வேண்டும். வடித்த அரிசி சேர்த்து அதிக தீயில் தண்ணீர் பெரும்பாலும் சுண்டி மேலே ஓட்டைகள் தெரியும் வரை வேக விடவும்.'),
            $t('டம்', 'மீதி புதினா கொத்தமல்லி தூவி, மூடியை மாவு அல்லது அலுமினிய பேப்பரால் சீல் செய்து மிகக் குறைந்த தீயில் (அல்லது தோசைக்கல் மேல்) 20 நிமிடம் டம் போடவும். 10 நிமிடம் கழித்து ஓரத்தில் இருந்து மெதுவாக கிளறவும். 65 °C க்கு மேல் வைக்கவும்.'),
        ]],
    'Sambar' => ['name_ta' => 'சாம்பார்',
        'notes' => 'Add vegetables in order of cooking time (drumstick and pumpkin first, brinjal last). For 250+ use two vessels and combine.',
        'notes_ta' => 'காய்களை வேகும் நேரப்படி சேர்க்கவும் (முருங்கை, பூசணி முதலில், கத்தரி கடைசியில்). 250 பேருக்கு மேல் இரண்டு பாத்திரங்களில் செய்து சேர்க்கவும்.',
        'steps_ta' => [
            $t('பருப்பு வேக வைத்தல்', 'துவரம் பருப்பை மஞ்சள் தூள், 10 லிட்டர் தண்ணீருடன் முழுமையாக குழைய வேக வைத்து நைசாக மசிக்கவும்.'),
            $t('காய் வேக வைத்தல்', 'புளிக்கரைசலில் சாம்பார் பொடி, உப்பு, 10 லிட்டர் தண்ணீருடன் காய்களை மிதமான தீயில் 12–15 நிமிடம் வேக விடவும் — முருங்கை எளிதாக குத்த வேண்டும், ஆனால் உருவம் குலையக் கூடாது.'),
            $t('சேர்த்தல்', 'பருப்பும் மீதி தண்ணீரும் சேர்த்து 10 நிமிடம் அடியில் இருந்து கிளறி கொதிக்க விடவும். கரண்டியின் பின்புறம் ஒட்டும் பதம் வேண்டும்.'),
            $t('தாளித்து முடித்தல்', 'எண்ணெயில் கடுகு, வெந்தயம் வெடித்ததும் வெங்காயம், பெருங்காயம், கறிவேப்பிலை வதக்கி, தக்காளி குழைய வதக்கி சாம்பாரில் ஊற்றி கொத்தமல்லி சேர்க்கவும். 65 °C க்கு மேல் வைக்கவும்.'),
        ]],
    'Rasam' => ['name_ta' => 'ரசம்',
        'notes' => 'Never boil rasam hard after adding the dal water. Make in batches close to service; reheated rasam loses its aroma.',
        'notes_ta' => 'பருப்பு தண்ணீர் சேர்த்த பிறகு ரசத்தை பலமாக கொதிக்க விடக் கூடாது. பரிமாறும் நேரத்துக்கு அருகில் செய்யவும்; சூடாக்கிய ரசம் வாசனை இழக்கும்.',
        'steps_ta' => [
            $t('அடிப்படை கொதிக்க வைத்தல்', 'புளிக்கரைசலில் தக்காளி, மஞ்சள் தூள், உப்பு, பூண்டு, ரசப் பொடி சேர்த்து மிதமான தீயில் 12–15 நிமிடம் புளி வாசனை போகும் வரை கொதிக்க விடவும்.'),
            $t('பருப்பு தண்ணீர்', 'வேக வைத்த பருப்பை மீதி தண்ணீரில் கரைத்து சேர்க்கவும். மேலே நுரை கட்டத் தொடங்கியதும் அடுப்பை அணைக்கவும் — அதற்குப் பிறகு கொதித்தால் கசக்கும்.'),
            $t('தாளித்தல்', 'நெய்யில் கடுகு வெடித்ததும் மிளகு, சீரகம், பெருங்காயம், கறிவேப்பிலை 20 வினாடி வறுத்து ரசத்தில் ஊற்றி கொத்தமல்லி சேர்த்து உடனே மூடவும். சூடாக வைக்கவும்.'),
        ]],
    'Vegetable Kurma' => ['name_ta' => 'வெஜிடபிள் குருமா',
        'notes' => 'Coconut paste splits if boiled hard — simmer only. For 250+ grind the paste in batches and cook in two vessels.',
        'notes_ta' => 'தேங்காய் விழுது பலமாக கொதித்தால் பிரியும் — மெதுவாக கொதிக்க விடவும். 250 பேருக்கு மேல் விழுதை தனித்தனியாக அரைத்து இரண்டு பாத்திரங்களில் செய்யவும்.',
        'steps_ta' => [
            $t('விழுது', 'தேங்காய், முந்திரி, சோம்பு, பச்சை மிளகாய் தண்ணீருடன் மிக நைசாக அரைக்கவும்.'),
            $t('அடிப்படை', 'எண்ணெயில் பட்டை, கிராம்பு வறுத்து, வெங்காயம் மென்மையாக லேசான பொன்னிறமாக வதக்கி, இஞ்சி பூண்டு விழுது பச்சை வாசனை போகும் வரை, பின் தக்காளி, மஞ்சள் தூள் மென்மையாகும் வரை வதக்கவும்.'),
            $t('காய்கறிகள்', 'காய்கறிகள், உப்பு, தண்ணீர் சேர்த்து மூடி மிதமான தீயில் 12–15 நிமிடம் வேக விடவும்.'),
            $t('முடித்தல்', 'தேங்காய் விழுது சேர்த்து குறைந்த தீயில் அடிக்கடி கிளறி 8–10 நிமிடம் கெட்டியாகி மேலே லேசாக எண்ணெய் தெரியும் வரை கொதிக்க விடவும்; பலமாக கொதித்தால் தேங்காய் பிரியும். 65 °C க்கு மேல் வைக்கவும்.'),
        ]],
    'Channa Masala' => ['name_ta' => 'சனா மசாலா',
        'notes' => 'Soak chana 8–10 hours; under-soaked chana never softens. Check one chickpea from each cooker batch before adding to the gravy.',
        'notes_ta' => 'கொண்டைக்கடலையை 8–10 மணி நேரம் ஊற வைக்கவும்; போதுமான ஊறாத கடலை வேகாது. ஒவ்வொரு குக்கரிலும் ஒரு கடலையை சோதித்த பிறகே கிரேவியில் சேர்க்கவும்.',
        'steps_ta' => [
            $t('கடலை வேக வைத்தல்', 'ஊறிய கொண்டைக்கடலையை உப்பு, புதிய தண்ணீருடன் குக்கரில் 5–6 விசில் வரை வேக வைக்கவும் — இரண்டு விரலால் எளிதாக நசுங்க வேண்டும். வேக வைத்த தண்ணீரை வைத்துக்கொள்ளவும்.'),
            $t('மசாலா', 'எண்ணெயில் வெங்காயத்தை மிதமான தீயில் 15 நிமிடம் நன்றாக பொன்னிறமாக வதக்கி, இஞ்சி பூண்டு விழுது, பின் தூள்களை கொஞ்சம் தண்ணீருடன் (கருகாமல்) சேர்த்து, தக்காளி விழுது சேர்த்து எண்ணெய் பிரியும் வரை வதக்கவும்.'),
            $t('கொதிக்க விடுதல்', 'கடலையை அதன் தண்ணீருடன் சேர்த்து 15 நிமிடம் கொதிக்க விடவும்; சில கடலைகளை மசித்து கிரேவியை கெட்டியாக்கவும். கொத்தமல்லி தூவி 65 °C க்கு மேல் வைக்கவும்.'),
        ]],
    'Cabbage Poriyal' => ['name_ta' => 'முட்டைகோஸ் பொரியல்',
        'notes' => 'Cook in batches of up to 10 kg — an overfilled kadai steams the cabbage and makes it watery.',
        'notes_ta' => 'ஒரு தடவைக்கு 10 கிலோ வரை மட்டும் — வாணலியில் அதிகம் போட்டால் முட்டைகோஸ் ஆவியில் வெந்து நீர்த்துவிடும்.',
        'steps_ta' => [
            $t('தாளித்தல்', $tempTa.' பச்சை மிளகாய், மஞ்சள் தூள் சேர்க்கவும்.'),
            $t('வதக்குதல்', 'முட்டைகோஸ், உப்பு சேர்த்து கிளறி மூடி மிதமான தீயில் 3 நிமிடத்துக்கு ஒரு முறை கிளறி 10–12 நிமிடம் மென்மையாக, லேசான மொறுமொறுப்புடன் வேக விடவும் — தண்ணீர் தேவையில்லை.'),
            $t('முடித்தல்', 'தேங்காய் துருவல் சேர்த்து அதிக தீயில் 2 நிமிடம் கிளறி ஈரம் போக்கவும்; வியர்க்காமல் இருக்க மூடாமல் வார்மரில் வைக்கவும்.'),
        ]],
    'Beans Poriyal' => ['name_ta' => 'பீன்ஸ் பொரியல்',
        'notes' => 'Chop beans finely and evenly so they cook in the same time. Cook in batches of up to 8 kg.',
        'notes_ta' => 'பீன்ஸை பொடியாக, சமமாக நறுக்கவும் — ஒரே நேரத்தில் வேகும். ஒரு தடவைக்கு 8 கிலோ வரை.',
        'steps_ta' => [
            $t('தாளித்தல்', $tempTa.' காய்ந்த மிளகாய் சேர்க்கவும்.'),
            $t('வேக வைத்தல்', 'பீன்ஸ், உப்பு, சிறிது தண்ணீர் தெளித்து மூடி மிதமான தீயில் 12–15 நிமிடம் மென்மையாக பச்சை நிறம் மாறாமல் வேக விடவும்; அடிபிடிக்காமல் அடிக்கடி கிளறவும்.'),
            $t('முடித்தல்', 'தேங்காய் துருவல் சேர்த்து 2 நிமிடம் கிளறவும். மூடாமல் வார்மரில் வைக்கவும்.'),
        ]],
    'Potato Fry' => ['name_ta' => 'உருளைக்கிழங்கு வறுவல்',
        'notes' => 'Do not over-boil potatoes — they break while roasting. Roast in a wide pan in one layer; for 250+ use several pans.',
        'notes_ta' => 'உருளைக்கிழங்கை அதிகம் வேக வைக்க வேண்டாம் — வறுக்கும் போது உடையும். அகலமான வாணலியில் ஒரே அடுக்கில் வறுக்கவும்; 250 பேருக்கு மேல் பல வாணலிகள்.',
        'steps_ta' => [
            $t('வேக வைத்தல்', 'உருளைக்கிழங்கை உப்புத் தண்ணீரில் கத்தி லேசான எதிர்ப்புடன் இறங்கும் வரை (சுமார் 15 நிமிடம்) வேக வைத்து ஆறவிட்டு தோல் உரித்து 1 அங்குல துண்டுகளாக நறுக்கவும்.'),
            $t('வறுத்தல்', 'அகலமான வாணலியில் எண்ணெய் சூடாக்கி கடுகு வெடித்ததும் கறிவேப்பிலை, பெருங்காயம், பின் உருளைக்கிழங்கை ஒரே அடுக்கில் போடவும். மிளகாய் தூள், மஞ்சள், உப்பு தூவி மிதமான தீயில் 3–4 நிமிடத்துக்கு ஒரு முறை மெதுவாக திருப்பி 15–20 நிமிடம் ஓரங்கள் மொறுமொறுப்பாகும் வரை வறுக்கவும்.'),
            $t('வைத்தல்', 'மூடாமல் வார்மரில் வைக்கவும்; மூடினால் மொறுமொறுப்பு போய்விடும்.'),
        ]],
    'Avial' => ['name_ta' => 'அவியல்',
        'notes' => 'Cut all vegetables into same-size batons. Add curd only after switching off the heat or it curdles.',
        'notes_ta' => 'எல்லா காய்களையும் ஒரே அளவு நீளத் துண்டுகளாக நறுக்கவும். அடுப்பை அணைத்த பிறகுதான் தயிர் சேர்க்கவும், இல்லையெனில் திரியும்.',
        'steps_ta' => [
            $t('காய் வேக வைத்தல்', 'கடினமான காய்களை (சேனை, வாழைக்காய், கேரட்) மஞ்சள், உப்பு, தண்ணீருடன் 8 நிமிடம் வேக வைத்து, மீதி காய்களை சேர்த்து 6–8 நிமிடம் உருவம் குலையாமல் வேக விடவும்.'),
            $t('தேங்காய்', 'தேங்காய், பச்சை மிளகாய், சீரகம் அதிக தண்ணீர் இல்லாமல் கரகரப்பாக அரைத்து காய்களில் சேர்த்து குறைந்த தீயில் 5 நிமிடம் வேக விடவும்.'),
            $t('முடித்தல்', 'அடுப்பை அணைத்து அடித்த தயிர் சேர்த்து, மேலே பச்சை தேங்காய் எண்ணெய், கறிவேப்பிலை சேர்க்கவும். மெதுவாக கலக்கவும் — அவியல் கெட்டியாக இருக்க வேண்டும். வெதுவெதுப்பாக வைக்கவும், கொதிக்க வேண்டாம்.'),
        ]],
    'Onion Pakoda' => ['name_ta' => 'வெங்காய பக்கோடா',
        'notes' => 'Fry close to service; pakoda goes soft in 45 minutes. Keep frying oil below smoking point and change it when dark.',
        'notes_ta' => 'பரிமாறும் நேரத்துக்கு அருகில் பொரிக்கவும்; 45 நிமிடத்தில் பக்கோடா மெத்தென்றாகும். எண்ணெய் புகையும் அளவுக்கு சூடாகக் கூடாது; கருத்ததும் மாற்றவும்.',
        'steps_ta' => [
            $t('கலத்தல்', 'வெங்காயத்துடன் உப்பு, மிளகாய், இஞ்சி, கறிவேப்பிலை சேர்த்து பிசறி 10 நிமிடம் வைக்கவும் — ஈரம் விடும். இரண்டு மாவும் மிளகாய் தூளும் சேர்த்து தண்ணீர் இல்லாமல் பிசறவும்; ஒட்டவில்லையென்றால் மட்டும் சிறிது தண்ணீர் தெளிக்கவும்.'),
            $t('பொரித்தல்', 'எண்ணெயை சுமார் 170 °C க்கு சூடாக்கி, சிறு சிறு தளர்வான கொத்துகளாக போட்டு மிதமான தீயில் திருப்பி 5–6 நிமிடம் பொன்னிறமாக மொறுமொறுப்பாக பொரிக்கவும்.'),
            $t('வடித்து வைத்தல்', 'ஓட்டை தட்டுகளில் ஒரே அடுக்கில் வடித்து 45 நிமிடத்துக்குள் பரிமாறவும். புகையும், நுரை வரும் அல்லது கருத்த எண்ணெயை எறியவும்.'),
        ]],
    'Rava Kesari' => ['name_ta' => 'ரவா கேசரி',
        'notes' => 'Use only food-grade colour, a few grams for 100 servings. For 250+ make in batches of 3 kg rava; large batches burn.',
        'notes_ta' => 'உணவுக்கு அனுமதிக்கப்பட்ட கலர் மட்டும், 100 பேருக்கு சில கிராம். 250 பேருக்கு மேல் 3 கிலோ ரவை அளவில் தனித்தனியாக செய்யவும்; பெரிய அளவில் அடிபிடிக்கும்.',
        'steps_ta' => [
            $t('நட்ஸ், ரவை வறுத்தல்', 'முந்திரி, திராட்சையை கொஞ்சம் நெய்யில் பொன்னிறமாக வறுத்து எடுக்கவும். ரவையை நெய்யில் குறைந்த தீயில் 8–10 நிமிடம் வாசனை வரும் வரை, பழுப்பாகாமல் வறுக்கவும்.'),
            $t('வேக வைத்தல்', 'கலர் சேர்த்த தண்ணீரை கொதிக்க வைத்து, ரவையை மெல்லிய தாரையாக தொடர்ந்து கிளறியபடி சேர்த்து, மூடி குறைந்த தீயில் 5 நிமிடம் வேக விடவும்.'),
            $t('சர்க்கரை, நெய்', 'சர்க்கரை சேர்க்கவும் — கலவை தளரும் — மீதி நெய்யை பகுதி பகுதியாக சேர்த்து குறைந்த தீயில் கெட்டியாகி பாத்திரத்தை விட்டு வரும் வரை கிளறவும். ஏலக்காய், நட்ஸ் சேர்க்கவும். வெதுவெதுப்பாக வைக்கவும்.'),
        ]],
    'Semiya Payasam' => ['name_ta' => 'சேமியா பாயசம்',
        'notes' => 'Milk-based: hold hot (above 65 °C) or chilled (below 5 °C), never lukewarm. Use a heavy-bottomed vessel and stir constantly.',
        'notes_ta' => 'பால் உணவு: 65 °C க்கு மேல் சூடாக அல்லது 5 °C க்கு கீழ் குளிர்ச்சியாக வைக்கவும், வெதுவெதுப்பாக வேண்டாம். கனமான அடிப்பாத்திரம், தொடர்ந்து கிளறவும்.',
        'steps_ta' => [
            $t('வறுத்தல்', 'சேமியாவை நெய்யில் குறைந்த தீயில் பொன்னிறமாக வறுக்கவும்; முந்திரி, திராட்சையை தனியாக வறுக்கவும்.'),
            $t('வேக வைத்தல்', 'கனமான பாத்திரத்தில் பாலும் தண்ணீரும் அடியில் பிடிக்காமல் கிளறி கொதிக்க வைத்து, சேமியா சேர்த்து மிதமான தீயில் 8–10 நிமிடம் மென்மையாக வேக விடவும்.'),
            $t('இனிப்பு சேர்த்தல்', 'சர்க்கரை சேர்த்து 5 நிமிடம் கொதிக்க விட்டு ஏலக்காய், நட்ஸ் சேர்க்கவும். ஆறும் போது கெட்டியாகும் — தேவையெனில் சூடான பால் சேர்க்கவும். 65 °C க்கு மேல் அல்லது 5 °C க்கு கீழ் வைக்கவும்.'),
        ]],
    'Sakkarai Pongal' => ['name_ta' => 'சர்க்கரைப் பொங்கல்',
        'notes' => 'Always melt and strain jaggery — it carries grit. Add jaggery syrup only after rice is fully cooked or the rice stays hard.',
        'notes_ta' => 'வெல்லத்தை கரைத்து வடிகட்டவும் — மண், கல் இருக்கும். அரிசி முழுமையாக வெந்த பிறகே வெல்லப் பாகு சேர்க்கவும், இல்லையெனில் அரிசி கெட்டியாகவே இருக்கும்.',
        'steps_ta' => [
            $t('அரிசி பருப்பு வேக வைத்தல்', 'அரிசியும் வறுத்த பருப்பும் பால், தண்ணீருடன் 30–35 நிமிடம் நன்றாக குழைய வேக வைத்து மசிக்கவும்.'),
            $t('வெல்லம்', 'வெல்லத்தை சிறிது தண்ணீரில் கரைத்து வடிகட்டி, பிசுபிசுப்பான பாகு வரும் வரை கொதிக்க வைத்து சாதத்தில் சேர்க்கவும். குறைந்த தீயில் 10 நிமிடம் கிளறி ஒன்று சேரும் வரை வேக விடவும்.'),
            $t('முடித்தல்', 'நெய்யை பகுதி பகுதியாக, ஏலக்காய், பச்சை கற்பூரம், வறுத்த நட்ஸ் சேர்க்கவும். மூடி வெதுவெதுப்பாக வைக்கவும்.'),
        ]],
    'Filter Coffee' => ['name_ta' => 'ஃபில்டர் காபி',
        'notes' => 'Decoction is best within 2 hours. For 250+ run several filters in parallel; mix coffee per jug, not in one big urn.',
        'notes_ta' => 'டிகாக்ஷன் 2 மணி நேரத்துக்குள் சிறந்தது. 250 பேருக்கு மேல் பல ஃபில்டர்களை ஒரே நேரத்தில் போடவும்; பெரிய பாத்திரத்தில் அல்ல, ஒவ்வொரு ஜக்கிலும் கலக்கவும்.',
        'steps_ta' => [
            $t('டிகாக்ஷன்', 'ஃபில்டரில் காபி தூள் போட்டு லேசாக அழுத்தி கொதிக்கும் தண்ணீர் ஊற்றி 20–30 நிமிடம் கெட்டியான டிகாக்ஷன் இறங்க விடவும். டிகாக்ஷனை மீண்டும் கொதிக்க வைக்க வேண்டாம்.'),
            $t('பால்', 'கனமான பாத்திரத்தில் பாலை காய்ச்சி, கொதிநிலைக்கு சற்று கீழே சூடான பாத்திரத்தில் வைக்கவும்.'),
            $t('கலத்தல்', 'ஒவ்வொரு முறையும் 1 பங்கு டிகாக்ஷனுக்கு 3 பங்கு சூடான பால், சர்க்கரை சேர்த்து இரண்டு ஜக்குகளில் மாற்றி ஊற்றி நுரை வரவிடவும். 30 நிமிடத்துக்குள் பரிமாறவும் — 2 மணி நேரம் ஆன டிகாக்ஷன் கசக்கும்.'),
        ]],
    'Buttermilk' => ['name_ta' => 'நீர் மோர்',
        'notes' => 'Use only potable chilled water. Keep the dispenser in shade and refill from the chiller in small lots.',
        'notes_ta' => 'குடிநீர் மட்டும், குளிர்ந்தது. டிஸ்பென்சரை நிழலில் வைத்து, குளிர்சாதனத்தில் இருந்து சிறு சிறு அளவில் நிரப்பவும்.',
        'steps_ta' => [
            $t('கலக்குதல்', 'தயிரை நைசாக அடித்து, கட்டி வராமல் அடித்தபடியே குளிர்ந்த தண்ணீரை கொஞ்சம் கொஞ்சமாக சேர்க்கவும்.'),
            $t('மணம் சேர்த்தல்', 'உப்பு, நசுக்கிய மிளகாய், இஞ்சி, கறிவேப்பிலை, கொத்தமல்லி, பெருங்காயம் சேர்த்து 15 நிமிடம் ஊற விடவும்; டிஸ்பென்சரில் ஊற்றுவதாக இருந்தால் வடிகட்டவும்.'),
            $t('குளிர்ச்சியாக வைத்தல்', '8 °C க்கு கீழ் வைத்து 3 மணி நேரத்துக்குள் பரிமாறவும்; குடிநீர் மட்டும், சுத்தமான மூடிய பாத்திரங்கள் பயன்படுத்தவும்.'),
        ]],
    'Chicken Biryani' => ['name_ta' => 'சிக்கன் டம் பிரியாணி',
        'notes' => 'This is the chicken dum biryani. Raw chicken: separate board, knife and gloves; marinate in the chiller, never at room temperature. For 250+ cook in separate vessels of 10 kg rice each.',
        'notes_ta' => 'இதுவே சிக்கன் டம் பிரியாணி. பச்சை கோழிக்கறிக்கு தனி பலகை, கத்தி, கையுறை; ஊற வைப்பதை குளிர்சாதனத்தில் மட்டும், அறை வெப்பத்தில் வேண்டாம். 250 பேருக்கு மேல் 10 கிலோ அரிசி அளவில் தனி பாத்திரங்கள்.',
        'steps_ta' => [
            $t('ஊற வைத்தல்', 'கோழிக்கறியை தயிர், பாதி இஞ்சி பூண்டு விழுது, மிளகாய் தூள், மஞ்சள், எலுமிச்சை, உப்புடன் கலந்து குளிர்சாதனத்தில் (5 °C க்கு கீழ்) குறைந்தது 1 மணி நேரம் ஊற வைக்கவும். பச்சை கறிக்கு தனி பலகை, கத்தி; கையாண்ட பிறகு கை கழுவவும்.'),
            $t('மசாலா', 'எண்ணெய், நெய்யில் முழு மசாலா வறுத்து, வெங்காயத்தை மிதமான தீயில் 15–20 நிமிடம் நன்றாக பொன்னிறமாக வதக்கவும். மீதி இஞ்சி பூண்டு விழுது, தக்காளி, பிரியாணி மசாலா சேர்த்து எண்ணெய் பிரியும் வரை வதக்கவும்.'),
            $t('கறி வேக வைத்தல்', 'ஊறிய கறியும் பாதி புதினா கொத்தமல்லியும் சேர்த்து மூடி மிதமான தீயில் 20 நிமிடம் வேக விடவும் — எலும்பருகே பிங்க் நிறம் இருக்கக் கூடாது, தடிமனான துண்டு 75 °C இருக்க வேண்டும்.'),
            $t('அரிசி, டம்', 'தண்ணீர் சேர்த்து கொதிக்க வைத்து சற்று அதிக உப்பாக சரிசெய்து, அரிசி சேர்த்து அதிக தீயில் தண்ணீர் பெரும்பாலும் சுண்டும் வரை வேக விடவும். புதினா கொத்தமல்லி தூவி சீல் செய்து மிகக் குறைந்த தீயில் 20–25 நிமிடம் டம் போடவும். 10 நிமிடம் கழித்து திறக்கவும்; 65 °C க்கு மேல் வைக்கவும்.'),
        ]],
];
